export class DefaultEntityRestCache implements EntityRestCache {
	constructor(private readonly entityRestClient: EntityRestClient, private readonly storage: CacheStorage) {}

	async load<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		id: PropertyType<T, "_id">,
		queryParameters?: Dict,
		extraHeaders?: Dict,
		ownerKey?: Aes128Key,
		providedOwnerEncSessionKey?: Uint8Array | null,
	): Promise<T> {
		const { listId, elementId } = expandId(id)

		// A cached instance may have been decrypted without the parent mail's session key.
		// Reload it when a key is provided so the key is available before decryption.
		const cachedEntity = providedOwnerEncSessionKey === undefined ? await this.storage.get(typeRef, listId, elementId) : null
		if (
			queryParameters?.version != null || //if a specific version is requested we have to load again
			cachedEntity == null
		) {
			const entity = await this.entityRestClient.load(typeRef, id, queryParameters, extraHeaders, ownerKey, providedOwnerEncSessionKey)
			if (queryParameters?.version == null && !isIgnoredType(typeRef)) {
				await this.storage.put(entity)
			}
			return entity
		}
		return cachedEntity
	}

	loadMultiple<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		listId: Id | null,
		elementIds: Array<Id>,
		providedOwnerEncSessionKeys?: Map<Id, Uint8Array>,
	): Promise<Array<T>> {
		if (isIgnoredType(typeRef)) {
			return this.entityRestClient.loadMultiple(typeRef, listId, elementIds, providedOwnerEncSessionKeys)
		}

		return this._loadMultiple(typeRef, listId, elementIds, providedOwnerEncSessionKeys)
	}

	setup<T extends SomeEntity>(listId: Id | null, instance: T, extraHeaders?: Dict, options?: EntityRestClientSetupOptions): Promise<Id> {
		return this.entityRestClient.setup(listId, instance, extraHeaders, options)
	}

	setupMultiple<T extends SomeEntity>(listId: Id | null, instances: Array<T>): Promise<Array<Id>> {
		return this.entityRestClient.setupMultiple(listId, instances)
	}
	}

	private async _loadMultiple<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		listId: Id | null,
		ids: Array<Id>,
		providedOwnerEncSessionKeys?: Map<Id, Uint8Array>,
	): Promise<Array<T>> {
		const entitiesInCache: T[] = []
		const idsToLoad: Id[] = []
		for (let id of ids) {
			const items = await this.storage.get(typeRef, listId, id)
			if (items != null && providedOwnerEncSessionKeys?.has(id) !== true) {
				entitiesInCache.push(items)
			} else {
				idsToLoad.push(id)
			}
		}
		const entitiesFromServer: T[] = []
		if (idsToLoad.length > 0) {
			const entities = await this.entityRestClient.loadMultiple(typeRef, listId, idsToLoad, providedOwnerEncSessionKeys)
			for (let entity of entities) {
				await this.storage.put(entity)
				entitiesFromServer.push(entity)
			}
		}

		return entitiesFromServer.concat(entitiesInCache)
	}

	async loadRange<T extends ListElementEntity>(typeRef: TypeRef<T>, listId: Id, start: Id, count: number, reverse: boolean): Promise<T[]> {
		const listIdToMailDetailsBlobIds: Map<Id, Array<Id>> = groupByAndMap(
			mailDetailsBlobMails,
			(m) => assertNotNull(m.mailDetails)[0],
			(m) => neverNull(m.mailDetails)[1],
		)
		for (let [listId, ids] of listIdToMailDetailsBlobIds) {
			const providedOwnerEncSessionKeys = this.ownerEncSessionKeysForList(mailDetailsBlobMails, (mail) => mail.mailDetails, listId)
			const mailDetailsBlobs = await this.loadInChunks(MailDetailsBlobTypeRef, listId, ids, providedOwnerEncSessionKeys)
			result.push(
				...mailDetailsBlobs.map((mailDetailsBlob) => {
					const mail = assertNotNull(mailDetailsBlobMails.find((m) => isSameId(m.mailDetails, mailDetailsBlob._id)))
					return MailWrapper.details(mail, mailDetailsBlob.details)
				}),
			)
		}
		// mailDetails stored in db (draft)
		let mailDetailsDraftMails = mails.filter((m) => isDetailsDraft(m))
		const listIdToMailDetailsDraftIds: Map<Id, Array<Id>> = groupByAndMap(
			mailDetailsDraftMails,
			(m) => assertNotNull(m.mailDetailsDraft)[0],
			(m) => neverNull(m.mailDetailsDraft)[1],
		)
		for (let [listId, ids] of listIdToMailDetailsDraftIds) {
			const providedOwnerEncSessionKeys = this.ownerEncSessionKeysForList(mailDetailsDraftMails, (mail) => mail.mailDetailsDraft, listId)
			const mailDetailsDrafts = await this.loadInChunks(MailDetailsDraftTypeRef, listId, ids, providedOwnerEncSessionKeys)
			result.push(
				...mailDetailsDrafts.map((draftDetails) => {
					const mail = assertNotNull(mailDetailsDraftMails.find((m) => isSameId(m.mailDetailsDraft, draftDetails._id)))
					return MailWrapper.details(mail, draftDetails.details)
				}),
			)
		}
		return result
	}

	loadAttachments(detailsList: MailWrapper[]): Promise<TutanotaFile[]> {
		const attachmentIds: IdTuple[] = []
		detailsList.forEach((d) => {
			attachmentIds.push(...d.getAttachmentIds())
		})
		const filesByList = groupBy(attachmentIds, (a) => a[0])
		const fileLoadingPromises: Array<Promise<Array<TutanotaFile>>> = []
		filesByList.forEach((fileIds, listId) => {
			fileLoadingPromises.push(
				this.loadInChunks(
					FileTypeRef,
					listId,
					fileIds.map((f) => f[1]),
				),
			)
		})
		// if (this._indexingCancelled) throw new CancelledError("cancelled indexing in loading attachments")
		return Promise.all(fileLoadingPromises).then((filesResults: TutanotaFile[][]) => filesResults.flat())
	}

	private ownerEncSessionKeysForList(mails: Mail[], getDetailsId: (mail: Mail) => IdTuple | null, listId: Id): Map<Id, Uint8Array> | undefined {
		const ownerEncSessionKeys = new Map<Id, Uint8Array>()
		for (const mail of mails) {
			const detailsId = getDetailsId(mail)
			if (detailsId != null && listIdPart(detailsId) === listId && mail._ownerEncSessionKey != null) {
				ownerEncSessionKeys.set(elementIdPart(detailsId), mail._ownerEncSessionKey)
			}
		}
		return ownerEncSessionKeys.size > 0 ? ownerEncSessionKeys : undefined
	}

	private loadInChunks<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		listId: Id | null,
		ids: Id[],
		providedOwnerEncSessionKeys?: Map<Id, Uint8Array>,
	): Promise<T[]> {
		const byChunk = splitInChunks(ENTITY_INDEXER_CHUNK, ids)
		return promiseMap(
			byChunk,
			(chunk) => {
				return chunk.length > 0 ? this._entity.loadMultiple(typeRef, listId, chunk, providedOwnerEncSessionKeys) : Promise.resolve([])
			},
			{
				concurrency: 2,
			},
		).then((entityResults) => entityResults.flat())
	}
}
					}),
				`can't load instances from server `,
			)
		}
		const doEvictToken = () => this.blobAccessTokenFacade.evictArchiveToken(archiveId)

		return doBlobRequestWithRetry(doBlobRequest, doEvictToken)
	}

	async _handleLoadMultipleResult<T extends SomeEntity>(
		typeRef: TypeRef<T>,
		loadedEntities: Array<any>,
		providedOwnerEncSessionKeys?: Map<Id, Uint8Array>,
	): Promise<Array<T>> {
		const model = await resolveTypeReference(typeRef)
		if (providedOwnerEncSessionKeys != null) {
			for (const instance of loadedEntities) {
				const id = Array.isArray(instance._id) ? instance._id[1] : instance._id
				const providedOwnerEncSessionKey = providedOwnerEncSessionKeys.get(id)
				if (providedOwnerEncSessionKey !== undefined) {
					instance._ownerEncSessionKey = providedOwnerEncSessionKey
				}
			}
		}

		// PushIdentifier was changed in the system model v43 to encrypt the name.
		// We check here to check the type only once per array and not for each element.
		if (isSameTypeRef(typeRef, PushIdentifierTypeRef)) {
			await promiseMap(loadedEntities, (instance) => this._crypto.applyMigrations(typeRef, instance), {
				concurrency: 5,
			})
		}

		return promiseMap(loadedEntities, (instance) => this._decryptMapAndMigrate(instance, model), { concurrency: 5 })
	}

	async _decryptMapAndMigrate<T>(instance: any, model: TypeModel): Promise<T> {
		let sessionKey
		try {
			sessionKey = await this._crypto.resolveSessionKey(model, instance)
		} catch (e) {
			if (e instanceof SessionKeyNotFoundError) {
				console.log("could not resolve session key", e)
				sessionKey = null // will result in _errors being set on the instance
			} else {
				throw e
			}
		}
		const decryptedInstance = await this.instanceMapper.decryptAndMapToInstance<T>(model, instance, sessionKey)
		return this._crypto.applyMigrationsForInstance<T>(decryptedInstance)
	}
